column1:
Does this compile?
// module-info.java
module com.example.app {
    requires java.base;
},Yes,No - java.base cannot be required,No - wrong syntax,No - module name invalid

Does this compile?
// module-info.java
module com.example.app {
    exports com.example.util;
}

// In package com.example.util
public class Helper { },Yes,No - exports requires requires,No - wrong syntax,No - package must be opened

Does this compile?
// module-info.java in com.example.provider
module com.example.provider {
    exports com.example.api;
}

// module-info.java in com.example.consumer
module com.example.consumer {
    requires com.example.provider;
},Yes,No - cyclic dependency,No - missing requires transitive,No - wrong syntax

Does this compile?
// module-info.java
module com.example.app {
    requires transitive java.sql;
    exports com.example.data;
},Yes,No - transitive only for custom modules,No - wrong syntax,No - java.sql cannot be transitive

Does this compile?
// module-info.java
module com.example.app {
    requires static java.compiler;
},Yes,No - static not allowed,No - wrong syntax,No - only for custom modules

Does this compile?
// module-info.java
module com.example.app {
    exports com.example.util to com.example.test;
},Yes,No - qualified exports not allowed,No - wrong syntax,No - missing comma

Does this compile?
// module-info.java
module com.example.app {
    opens com.example.internal;
},Yes,No - opens not allowed,No - wrong syntax,No - must use exports

Does this compile?
// module-info.java
open module com.example.app {
    requires java.sql;
},Yes,No - open module cannot have requires,No - wrong syntax,No - open module invalid

Does this compile?
// module-info.java
open module com.example.app {
    exports com.example.api;
},No - open module cannot export,Yes,No - wrong syntax,No - missing requires

Does this compile?
// module-info.java
module com.example.app {
    uses java.sql.Driver;
},Yes,No - uses requires provides,No - wrong syntax,No - Driver not a service

Does this compile?
// module-info.java
module com.example.app {
    provides com.example.Service
        with com.example.ServiceImpl;
},Yes,No - provides requires uses,No - wrong syntax,No - missing implements

Does this compile?
// module-info.java
module com.example.app {
    exports com.example.api;
    exports com.example.api;
},No - duplicate exports,Yes,No - wrong syntax,No - requires alias

Does this compile?
// module-info.java
module com.example.app {
    requires com.example.provider;
    requires com.example.provider;
},No - duplicate requires,Yes,No - wrong syntax,No - use requires transitive

Does this compile?
// module-info.java
package com.example;

module com.example.app {
    exports com.example.api;
},No - module-info cannot be in package,Yes,No - wrong syntax,No - package must be default

Does this compile?
// module-info.java
module com-example-app {
    exports com.example.api;
},No - module names cannot have dashes,Yes,No - wrong syntax,No - must use dots

What is the output?
// module com.app
module com.app {
    exports com.app.api;
}

// In com.app.api
public class Service {
    public static void test() {
        System.out.println("Service");
    }
}

// module com.client requires com.app and calls Service.test(),Service,Compilation error,Access denied,Module not found

What is the output?
// module com.app
module com.app {
    // no exports
}

// In com.app.api
public class Service {
    public static void test() {
        System.out.println("Service");
    }
}

// module com.client requires com.app and tries to call Service.test(),Compilation error - package not exported,Service,Access denied,Module not found

What is the output?
// module com.app
module com.app {
    exports com.app.api;
}

// In com.app.api
class Service {
    public static void test() {
        System.out.println("Service");
    }
}

// module com.client requires com.app and tries to use Service,Compilation error - class not public,Service,Access denied,Module not found

