    provides com.example.api.Logger
        with com.provider.impl.ConsoleLogger;
    exports com.example.api;
}

// module com.app uses the service
module com.app {
    requires com.provider;
    uses com.example.api.Logger;
},Compiles and runs,Compilation error,Service not found,Provider not accessible

