import java.util.ServiceLoader;

// In module that uses Logger service
ServiceLoader<Logger> loader = ServiceLoader.load(Logger.class);
Iterator<Logger> it = loader.iterator();
if (it.hasNext()) {
    Logger logger = it.next();
    logger.log("Test");
}

// Assume one provider exists,Test is logged,Compilation error,Service not found,NullPointerException

