// ServiceLoader stream() vs iterator()

ServiceLoader<Service> loader = ServiceLoader.load(Service.class);

// Using stream()
long count1 = loader.stream()
    .map(ServiceLoader.Provider::get)
    .count();

// Using iterator()
long count2 = 0;
for (Service s : loader) count2++;

// Both count providers - difference?,stream() can filter before instantiation,No difference,stream() is faster,iterator() is lazy

